contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);
        require(amount > 0);

        c.sudicideAnyone(); if (__ESBMC_reverted()) return;

        uint beforeC = address(c).balance;
        uint beforeSelf = address(this).balance;

        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint afterC = address(c).balance;
        uint afterSelf = address(this).balance;

        assert(
            (!reverted && afterC == 0 && afterSelf >= beforeSelf + beforeC) ||
            (reverted && afterC == beforeC && afterSelf == beforeSelf)
        );
    }
}

