// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleSuicide} from "../src/SimpleSuicide.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleSuicide c;

    function setUp() public {
        c = new SimpleSuicide();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        vm.assume(amount > 0);
        try c.sudicideAnyone() {} catch { return; }
        uint beforeC = address(c).balance;
        uint beforeSelf = address(this).balance;
        bool reverted;
        try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
        uint afterC = address(c).balance;
        uint afterSelf = address(this).balance;
        assertTrue((!reverted && afterC == 0 && afterSelf >= beforeSelf + beforeC) ||
            (reverted && afterC == beforeC && afterSelf == beforeSelf));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
